insert into public.destinations (id, slug, name, region, tagline, description, hero_image, best_seasons, lat, lng, featured, published) values
  ('d0000000-0000-4000-8000-000000000001', 'everest-khumbu', 'Everest & Khumbu', 'Khumbu', 'Sherpa villages, glacier valleys and the highest ground on earth.', 'The Khumbu is the valley system below Everest: pine forest and suspension bridges out of Lukla, the market town of Namche Bazaar, monasteries at Tengboche, and high, bare moraine beyond Dingboche. Treks here gain altitude quickly, so acclimatisation days are part of the route rather than an optional extra. Flights to Lukla are weather-dependent and often move at short notice.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Everest%2C_Himalayas.jpg/1920px-Everest%2C_Himalayas.jpg', array['spring', 'autumn']::text[], 27.8048, 86.7132, true, true),
  ('d0000000-0000-4000-8000-000000000002', 'annapurna-region', 'Annapurna Region', 'Annapurna', 'Rhododendron forest, Gurung villages and the Annapurna sanctuary.', 'The Annapurna region is reached from Pokhara and covers a huge range of country: the terraced foothills around Ghandruk and Ghorepani, the Modi Khola gorge leading to Annapurna Base Camp, and the high passes of the Annapurna Circuit further north. Teahouse networks are dense, which makes shorter itineraries possible than in the Khumbu.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Annapurna_Massif-IMG_5221-Pano.jpg/1920px-Annapurna_Massif-IMG_5221-Pano.jpg', array['spring', 'autumn', 'winter']::text[], 28.2096, 83.9856, true, true),
  ('d0000000-0000-4000-8000-000000000003', 'langtang-helambu', 'Langtang & Helambu', 'Langtang', 'The closest big Himalaya to Kathmandu, by road from Syabrubesi.', 'Langtang National Park sits directly north of Kathmandu and is reached by a long road journey to Syabrubesi rather than a flight. The valley climbs through oak and bamboo forest to Langtang Village and Kyanjin Gompa, with Tamang culture, cheese-making and close views of Langtang Lirung. Helambu to the east offers lower, village-to-village walking.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Kyanjin_Gompa_Village_Rasuwa.jpg/1920px-Kyanjin_Gompa_Village_Rasuwa.jpg', array['spring', 'autumn']::text[], 28.2404, 85.5602, true, true),
  ('d0000000-0000-4000-8000-000000000004', 'manaslu-circuit', 'Manaslu', 'Manaslu', 'A restricted-area circuit around the eighth-highest mountain.', 'The Manaslu Circuit circles Manaslu from the Budhi Gandaki gorge to the Larke Pass and down into the Marsyangdi valley. It is a restricted area: permits are arranged through a licensed agency, trekkers travel in groups of at least two, and the teahouse network is thinner and more basic than on the Annapurna Circuit. Landslides and weather can close sections of the road approach.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Mt_Manaslu_from_Manaslu_basecamp.jpg/1920px-Mt_Manaslu_from_Manaslu_basecamp.jpg', array['spring', 'autumn']::text[], 28.549, 84.56, false, true),
  ('d0000000-0000-4000-8000-000000000005', 'mustang', 'Mustang', 'Mustang', 'Rain-shadow desert, cliff caves and the walled city of Lo Manthang.', 'Upper Mustang lies north of the Annapurna and Dhaulagiri ranges in the rain shadow, so it stays dry when the rest of Nepal is under monsoon. The trail follows the Kali Gandaki from Jomsom through Kagbeni to Lo Manthang, past eroded cliffs, gompas and villages that were part of the Kingdom of Lo. Access beyond Kagbeni requires a restricted-area permit and a licensed agency.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/The_kingdom_of_Lo%2C_Lomangthang%2C_Upper_Mustang_%28Pano%29.jpg/1920px-The_kingdom_of_Lo%2C_Lomangthang%2C_Upper_Mustang_%28Pano%29.jpg', array['spring', 'summer', 'autumn']::text[], 29.19, 83.956, false, true),
  ('d0000000-0000-4000-8000-000000000006', 'kathmandu-valley', 'Kathmandu Valley', 'Kathmandu Valley', 'Ridge walks, Newar towns and Himalayan views above the capital.', 'The Kathmandu Valley rim has a network of walking trails between Newar towns such as Nagarkot, Dhulikhel, Balthali and Kirtipur. Altitudes stay modest and you can walk between villages with a day pack, using local buses or a driver to link the ends. On clear mornings the northern horizon fills with Langtang, Ganesh and, from the eastern rim, Everest.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Nepal_-_Bhaktapur_Nyatapola_temple.jpg/1920px-Nepal_-_Bhaktapur_Nyatapola_temple.jpg', array['spring', 'autumn', 'winter']::text[], 27.7172, 85.324, false, true),
  ('d0000000-0000-4000-8000-000000000007', 'chitwan-national-park', 'Chitwan National Park', 'Chitwan', 'Grassland and riverine forest in the Terai lowlands.', 'Chitwan, Nepal''s first national park, protects sal forest, tall grassland and the floodplain of the Rapti and Narayani rivers. Walking is only permitted with a licensed guide, and most wildlife viewing happens on foot in the buffer zone, by canoe, or from a jeep. It is a low-altitude contrast to a mountain trek and easy to combine with Pokhara or Kathmandu.', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg/1920px-Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg', array['autumn', 'winter', 'spring']::text[], 27.579, 84.494, false, true)
insert into public.trails (id, slug, name, summary, description, region, destination_id, difficulty, activity, distance_km, duration_days, max_elevation_m, elevation_gain_m, start_point_name, start_lat, start_lng, best_seasons, hero_image, gallery, route_geojson, itinerary, facilities, safety_notes, permit_info, permits_required, is_sample, featured, published) values
  ('a0000000-0000-4000-8000-000000000001', 'everest-base-camp-trek', 'Everest Base Camp Trek', 'The classic Khumbu route from Lukla to Everest Base Camp and Kala Patthar, with acclimatisation built into the itinerary.', 'The EBC trek follows the Dudh Koshi valley from Lukla through Phakding and Namche Bazaar, then climbs past Tengboche and Dingboche to the moraine at Gorak Shep. The high point for most walkers is Kala Patthar, which looks directly onto the Khumbu Icefall and the south face of Everest. Days above 3,000 m are short on walking hours and long on rest, because acclimatisation is the constraint rather than distance. Lukla flights are frequently delayed by weather; build a buffer day into your ticket and travel insurance.', 'Khumbu', 'd0000000-0000-4000-8000-000000000001', 'hard', 'trekking', 130, 14, 5545, 3200, 'Lukla (Tenzing–Hillary Airport)', 27.6875, 86.7315, array['spring', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Everest%2C_Himalayas.jpg/1920px-Everest%2C_Himalayas.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Namche_Bazaar%2C_Mountains%2C_Nepal.jpg/1920px-Namche_Bazaar%2C_Mountains%2C_Nepal.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Sunset_view_of_Everest.jpg/1920px-Sunset_view_of_Everest.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Namche_Bazaar%2C_Nepal.jpg/1920px-Namche_Bazaar%2C_Nepal.jpg']::text[], '{"type":"LineString","coordinates":[[86.7315,27.6875],[86.7128,27.7408],[86.7189,27.7719],[86.7132,27.8048],[86.7644,27.836],[86.832,27.8929],[86.811,27.946],[86.8293,27.9772],[86.8528,28.0026]]}'::jsonb, '[{"day":1,"title":"Lukla → Phakding","description":"Descend from the airstrip to the Dudh Koshi and follow it north through small villages.","altitudeM":2610,"walkingHours":"3–4 h","accommodation":"Teahouse, Phakding"},{"day":2,"title":"Phakding → Namche Bazaar","description":"Suspension bridges, the Sagarmatha park gate at Monjo and a long climb to Namche.","altitudeM":3440,"walkingHours":"6 h","accommodation":"Teahouse, Namche"},{"day":3,"title":"Acclimatisation in Namche","description":"Short climb to Syangboche and the Everest View Hotel, then rest. Stay the night at the same altitude.","altitudeM":3440,"walkingHours":"3 h optional","accommodation":"Teahouse, Namche"},{"day":4,"title":"Namche → Tengboche","description":"Contour above the Dudh Koshi, cross at Phunki Tenga and climb to the monastery ridge.","altitudeM":3860,"walkingHours":"5 h","accommodation":"Teahouse, Tengboche"},{"day":5,"title":"Tengboche → Dingboche","description":"Forest gives way to dwarf juniper; a side valley opens toward Ama Dablam.","altitudeM":4410,"walkingHours":"5 h","accommodation":"Teahouse, Dingboche"},{"day":6,"title":"Acclimatisation in Dingboche","description":"Climb the Nangkartshang ridge for views of Makalu and Island Peak, then descend to sleep low.","altitudeM":4410,"walkingHours":"4 h optional","accommodation":"Teahouse, Dingboche"},{"day":7,"title":"Dingboche → Lobuche","description":"Pass the memorials above Thukla and follow the terminal moraine of the Khumbu glacier.","altitudeM":4910,"walkingHours":"5 h","accommodation":"Teahouse, Lobuche"},{"day":8,"title":"Lobuche → Gorak Shep","description":"Rough walking along the lateral moraine. Afternoon acclimatisation walk if you feel well.","altitudeM":5140,"walkingHours":"4 h","accommodation":"Teahouse, Gorak Shep"},{"day":9,"title":"Gorak Shep → Everest Base Camp","description":"Follow the glacier to base camp and the Khumbu Icefall viewpoint, then return to Gorak Shep.","altitudeM":5364,"walkingHours":"6–7 h","accommodation":"Teahouse, Gorak Shep"},{"day":10,"title":"Kala Patthar → Pheriche","description":"Pre-dawn climb to Kala Patthar for the south face, then descend to Pheriche.","altitudeM":5545,"walkingHours":"7–8 h","accommodation":"Teahouse, Pheriche"},{"day":11,"title":"Pheriche → Namche Bazaar","description":"A long, mostly descending day back through Tengboche.","altitudeM":3440,"walkingHours":"7 h","accommodation":"Teahouse, Namche"},{"day":12,"title":"Namche → Lukla","description":"Retrace the valley past Monjo and Phakding.","altitudeM":2860,"walkingHours":"7–8 h","accommodation":"Lodge, Lukla"},{"day":13,"title":"Contingency day","description":"Reserved for weather, illness or a slower acclimatisation schedule. Do not plan a fixed international flight for the next day.","altitudeM":2860,"walkingHours":"—","accommodation":"Lodge, Lukla"},{"day":14,"title":"Lukla → Kathmandu","description":"Morning flight to Kathmandu, weather permitting.","altitudeM":1400,"walkingHours":"—","accommodation":"Hotel, Kathmandu"}]'::jsonb, array['Teahouses with beds and shared bathrooms along the whole route', 'Hot showers and device charging at most lodges, for a fee', 'ATMs in Namche Bazaar (unreliable — carry cash)', 'Bottled water and purification refill points; avoid single-use plastic', 'Basic medical posts at Namche and Pheriche', 'Everest Link / local wifi cards in most villages']::text[], 'This route reaches 5,545 m. Ascend no more than roughly 500 m per sleeping night above 3,000 m, keep the rest days, and descend immediately if symptoms of acute mountain sickness worsen. Two people in the party should carry a pulse oximeter and know the location of the Pheriche medical post. Weather can shut Lukla for days; keep insurance that covers helicopter evacuation and trip delay. Do not rely on mobile signal above Namche.', 'Sagarmatha National Park entry permit and Khumbu Pasanglhamu Rural Municipality fee. Confirm current requirements and fees with the Nepal Tourism Board before travelling; permits are checked at Monjo.', array['Sagarmatha National Park permit', 'Khumbu Pasanglhamu Rural Municipality fee']::text[], true, true, true),
  ('a0000000-0000-4000-8000-000000000002', 'annapurna-base-camp-trek', 'Annapurna Base Camp Trek', 'Gurung villages, the Modi Khola gorge and the amphitheatre of Annapurna Base Camp in a ten-day loop from Pokhara.', 'From Nayapul the trail climbs through Ghorepani and Tadapani to Chhomrong, then enters the narrow Modi Khola valley to Annapurna Base Camp. The sanctuary is a natural amphitheatre ringed by Annapurna I, Annapurna South, Machapuchare and Hiunchuli, reached in about a week from Pokhara. Teahouses are close together, which makes the route flexible and a reasonable first Himalayan trek for fit walkers, though the stone steps and total ascent are demanding.', 'Annapurna', 'd0000000-0000-4000-8000-000000000002', 'moderate', 'trekking', 115, 10, 4130, 3300, 'Nayapul, Myagdi', 28.2711, 83.8083, array['spring', 'autumn', 'winter']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Annapurna_Base_Camp_with_snow.jpg/1920px-Annapurna_Base_Camp_with_snow.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Annapurna_Massif-IMG_5221-Pano.jpg/1920px-Annapurna_Massif-IMG_5221-Pano.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Machapuchare_%28Fishtail_Mountain%29.jpg/1920px-Machapuchare_%28Fishtail_Mountain%29.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Panorama_from_poonhill-2019-BJ.jpg/1920px-Panorama_from_poonhill-2019-BJ.jpg']::text[], '{"type":"LineString","coordinates":[[83.8083,28.2711],[83.7835,28.3267],[83.6994,28.4023],[83.7446,28.3935],[83.8207,28.3776],[83.82,28.3522],[83.8616,28.3577],[83.8722,28.3764],[83.8783,28.3869]]}'::jsonb, '[{"day":1,"title":"Pokhara → Nayapul → Tikhedhunga","description":"Road transfer, then easy walking up the Bhurungdi Khola.","altitudeM":1540,"walkingHours":"4 h","accommodation":"Teahouse, Tikhedhunga"},{"day":2,"title":"Tikhedhunga → Ghorepani","description":"The long stone staircase to Ulleri, then rhododendron forest to Ghorepani.","altitudeM":2860,"walkingHours":"6–7 h","accommodation":"Teahouse, Ghorepani"},{"day":3,"title":"Poon Hill → Tadapani","description":"Sunrise on Poon Hill, then an undulating ridge walk through forest.","altitudeM":2630,"walkingHours":"6 h","accommodation":"Teahouse, Tadapani"},{"day":4,"title":"Tadapani → Chhomrong","description":"Descend to Chuile, climb to Chhomrong with Annapurna South ahead.","altitudeM":2170,"walkingHours":"5 h","accommodation":"Teahouse, Chhomrong"},{"day":5,"title":"Chhomrong → Bamboo","description":"Steep descent to the Chhomrong Khola, then forest above the Modi Khola.","altitudeM":2310,"walkingHours":"5 h","accommodation":"Teahouse, Bamboo"},{"day":6,"title":"Bamboo → Deurali","description":"Bamboo, bamboo, then high forest; the gorge narrows and the air cools.","altitudeM":3230,"walkingHours":"5 h","accommodation":"Teahouse, Deurali"},{"day":7,"title":"Deurali → Annapurna Base Camp","description":"Pass Machhapuchhre Base Camp and continue into the sanctuary.","altitudeM":4130,"walkingHours":"4–5 h","accommodation":"Teahouse, Annapurna Base Camp"},{"day":8,"title":"Annapurna Base Camp → Bamboo","description":"Sunrise on the Annapurnas, then a long descent out of the gorge.","altitudeM":2310,"walkingHours":"7 h","accommodation":"Teahouse, Bamboo"},{"day":9,"title":"Bamboo → Jhinu Danda","description":"Climb back to Chhomrong and descend to the hot springs at Jhinu.","altitudeM":1780,"walkingHours":"6 h","accommodation":"Teahouse, Jhinu Danda"},{"day":10,"title":"Jhinu Danda → Nayapul → Pokhara","description":"River-level walk out, then road transfer to Pokhara.","altitudeM":1400,"walkingHours":"4 h","accommodation":"Hotel, Pokhara"}]'::jsonb, array['Dense teahouse network, roughly every two hours of walking', 'Hot showers and charging at most lodges below Deurali', 'No ATMs beyond Nayapul — carry Nepali rupees', 'Seasonal medical post near Himalaya and a rescue helicopter pad at Chhomrong', 'Jhinu Danda hot springs near the end of the route']::text[], 'The sanctuary sits at 4,130 m and is surrounded by steep terrain; avalanches are possible on the slopes above the route in heavy snow. Doble and Deurali are known avalanche-prone stretches — ask locally about conditions and do not walk into the gorge in poor visibility. Leeches and slick stone steps are common in the monsoon. Fly or drive out early in the day if you have a fixed international connection.', 'Annapurna Conservation Area Project (ACAP) entry permit and a Trekkers’ Information Management System (TIMS) card. Both are checked at Nayapul and Chhomrong; confirm current fees with the Nepal Tourism Board.', array['ACAP permit', 'TIMS card']::text[], true, true, true),
  ('a0000000-0000-4000-8000-000000000003', 'poon-hill-sunrise-trek', 'Poon Hill Sunrise Trek', 'A short Ghorepani loop with a dawn climb to the Poon Hill viewpoint over Dhaulagiri and Annapurna South.', 'Poon Hill is the most efficient introduction to Himalayan trekking from Pokhara: three or four days of walking, a maximum altitude of 3,210 m, and a sunrise viewpoint that takes in Dhaulagiri, Nilgiri, Annapurna South and Machapuchare. The route uses the same teahouse trail as the Annapurna Base Camp trek as far as Ghorepani, then loops back through Ghandruk. Stone staircases make the ascent harder than the distance suggests.', 'Annapurna', 'd0000000-0000-4000-8000-000000000002', 'easy', 'trekking', 40, 4, 3210, 1350, 'Nayapul, Myagdi', 28.2711, 83.8083, array['spring', 'autumn', 'winter']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Poon_hill_viewpoint.jpg/1920px-Poon_hill_viewpoint.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Panorama_from_poonhill-2019-BJ.jpg/1920px-Panorama_from_poonhill-2019-BJ.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Annapurna_Massif-IMG_5221-Pano.jpg/1920px-Annapurna_Massif-IMG_5221-Pano.jpg']::text[], '{"type":"LineString","coordinates":[[83.8083,28.2711],[83.7835,28.3267],[83.6994,28.4023],[83.696,28.408],[83.8079,28.3773],[83.8083,28.2711]]}'::jsonb, '[{"day":1,"title":"Pokhara → Nayapul → Ulleri","description":"Easy valley walking, then the stone steps to Ulleri village.","altitudeM":1960,"walkingHours":"5 h","accommodation":"Teahouse, Ulleri"},{"day":2,"title":"Ulleri → Ghorepani","description":"Rhododendron and oak forest with repeated views of Annapurna South.","altitudeM":2860,"walkingHours":"5 h","accommodation":"Teahouse, Ghorepani"},{"day":3,"title":"Poon Hill → Ghandruk","description":"Pre-dawn 45-minute climb to the viewpoint, then a long forest traverse to Ghandruk.","altitudeM":1940,"walkingHours":"7 h","accommodation":"Teahouse, Ghandruk"},{"day":4,"title":"Ghandruk → Nayapul → Pokhara","description":"Descend through terraced fields and drive back to Pokhara.","altitudeM":1400,"walkingHours":"3–4 h","accommodation":"Hotel, Pokhara"}]'::jsonb, array['Teahouses in every village on the route', 'Hot showers and charging available at a small fee', 'Poon Hill has a small entry fee and a viewing tower', 'Ghandruk has a Gurung museum and several lodges']::text[], 'There is no technical difficulty, but the staircase sections are hard on knees and the ridge is exposed in bad weather. Mornings at Poon Hill are cold and often cloudy in summer; carry a windproof layer and a head torch. Winter snow is possible above Ghorepani.', 'ACAP entry permit and TIMS card. Confirm current fees with the Nepal Tourism Board; the checkpoint is at Nayapul.', array['ACAP permit', 'TIMS card']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000004', 'mardi-himal-trek', 'Mardi Himal Trek', 'A short ridge ascent off the Annapurna Base Camp trail to Mardi Himal Base Camp below Machapuchare.', 'The Mardi Himal route leaves the main ABC trail near Deurali and climbs a forested ridge to Low Camp, High Camp and Mardi Himal Base Camp at around 4,500 m. Because it is a ridge rather than a valley, the views of Machapuchare, Annapurna South and Hiunchuli stay with you for most of the walk. It is short enough for a five-day trip from Pokhara but climbs fast, so the altitude should be treated with respect.', 'Annapurna', 'd0000000-0000-4000-8000-000000000002', 'moderate', 'trekking', 50, 5, 4500, 2350, 'Kande, Kaski', 28.3423, 83.8732, array['spring', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Machapuchare_%28Fishtail_Mountain%29.jpg/1920px-Machapuchare_%28Fishtail_Mountain%29.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Annapurna_Massif-IMG_5221-Pano.jpg/1920px-Annapurna_Massif-IMG_5221-Pano.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Panorama_from_poonhill-2019-BJ.jpg/1920px-Panorama_from_poonhill-2019-BJ.jpg']::text[], '{"type":"LineString","coordinates":[[83.8732,28.3423],[83.8861,28.3712],[83.9042,28.3901],[83.9174,28.4107],[83.9257,28.4322],[83.8934,28.3985]]}'::jsonb, '[{"day":1,"title":"Pokhara → Kande → Deurali","description":"Road to Kande, then forest trail to Deurali on the ridge.","altitudeM":2100,"walkingHours":"4–5 h","accommodation":"Teahouse, Deurali"},{"day":2,"title":"Deurali → Low Camp","description":"Leave the main trail and climb through mossy rhododendron forest.","altitudeM":2990,"walkingHours":"5 h","accommodation":"Teahouse, Low Camp"},{"day":3,"title":"Low Camp → High Camp","description":"Short, steep day onto the open ridge above the treeline.","altitudeM":3580,"walkingHours":"3–4 h","accommodation":"Teahouse, High Camp"},{"day":4,"title":"High Camp → Mardi Himal Base Camp → Siding","description":"Alpine start for the base camp viewpoint, then descend a long way to Siding.","altitudeM":4500,"walkingHours":"8 h","accommodation":"Teahouse, Siding"},{"day":5,"title":"Siding → Pokhara","description":"Walk out to the road and drive to Pokhara.","altitudeM":1400,"walkingHours":"2–3 h","accommodation":"Hotel, Pokhara"}]'::jsonb, array['Basic teahouses at Deurali, Forest Camp, Low Camp, High Camp and Siding', 'Limited electricity above Low Camp', 'Shared bathrooms at High Camp; no hot showers', 'No shops or ATMs after Kande']::text[], 'The ridge is exposed to wind, cloud and lightning, and the altitude gain is quick for a short trek. High Camp lodges are simple and cold; carry a warm sleeping bag. If you have a headache that does not respond to rest and hydration at High Camp, descend rather than continue to base camp.', 'ACAP entry permit and TIMS card, checked at the trailhead near Kande.', array['ACAP permit', 'TIMS card']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000005', 'langtang-valley-trek', 'Langtang Valley Trek', 'A road-accessible valley trek to Kyanjin Gompa, with a side climb of Kyanjin Ri and close views of Langtang Lirung.', 'The Langtang Valley trek starts at Syabrubesi after a long drive from Kathmandu and follows the Langtang Khola through Lama Hotel and Langtang Village to Kyanjin Gompa. It is one of the closest high mountain valleys to the capital and is less busy than the Annapurna and Khumbu routes. The valley was badly affected by the 2015 earthquake and landslide; rebuilding continues, and some trails and lodges change from season to season.', 'Langtang', 'd0000000-0000-4000-8000-000000000003', 'moderate', 'trekking', 70, 8, 4773, 3300, 'Syabrubesi, Rasuwa', 28.1636, 85.3367, array['spring', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Langtang_Trekking_Trail_Rasuwa_Nepal.jpg/1920px-Langtang_Trekking_Trail_Rasuwa_Nepal.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Kyanjin_Gompa_Village_Rasuwa.jpg/1920px-Kyanjin_Gompa_Village_Rasuwa.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Gokyo_Lakes%2C_Dudh_Pokhari%2C_Nepal%2C_Himalayas.jpg/1920px-Gokyo_Lakes%2C_Dudh_Pokhari%2C_Nepal%2C_Himalayas.jpg']::text[], '{"type":"LineString","coordinates":[[85.3367,28.1636],[85.3776,28.1812],[85.5171,28.2091],[85.533,28.226],[85.5602,28.2404],[85.564,28.247]]}'::jsonb, '[{"day":1,"title":"Kathmandu → Syabrubesi","description":"Long, bumpy road journey along the Trishuli valley.","altitudeM":1460,"walkingHours":"—","accommodation":"Guesthouse, Syabrubesi"},{"day":2,"title":"Syabrubesi → Lama Hotel","description":"Follow the Langtang Khola through bamboo and oak forest.","altitudeM":2380,"walkingHours":"5–6 h","accommodation":"Teahouse, Lama Hotel"},{"day":3,"title":"Lama Hotel → Langtang Village","description":"Climb out of the gorge into open valley below Langtang Lirung.","altitudeM":3430,"walkingHours":"6 h","accommodation":"Teahouse, Langtang Village"},{"day":4,"title":"Langtang Village → Kyanjin Gompa","description":"Gentle climb past Mundu to the monastery and cheese factory.","altitudeM":3830,"walkingHours":"3–4 h","accommodation":"Teahouse, Kyanjin Gompa"},{"day":5,"title":"Kyanjin Ri acclimatisation","description":"Climb Kyanjin Ri for the glacier and Langtang Lirung panorama, then rest.","altitudeM":4773,"walkingHours":"4–5 h","accommodation":"Teahouse, Kyanjin Gompa"},{"day":6,"title":"Kyanjin Gompa → Lama Hotel","description":"Long descent back down the valley.","altitudeM":2380,"walkingHours":"6–7 h","accommodation":"Teahouse, Lama Hotel"},{"day":7,"title":"Lama Hotel → Syabrubesi","description":"Forest walking back to the road head.","altitudeM":1460,"walkingHours":"5 h","accommodation":"Guesthouse, Syabrubesi"},{"day":8,"title":"Syabrubesi → Kathmandu","description":"Return drive, or continue to Helambu via a connecting route.","altitudeM":1400,"walkingHours":"—","accommodation":"Hotel, Kathmandu"}]'::jsonb, array['Teahouses at roughly two-hour intervals up the valley', 'Kyanjin Gompa has a cheese factory and a handful of lodges', 'No ATMs beyond Kathmandu — carry cash', 'Hydroelectric supply is limited; expect charging fees']::text[], 'The drive from Kathmandu is long and can be affected by landslides in monsoon and winter snow. Kyanjin Ri is a steep, unmaintained viewpoint climb; turn back in cloud or icy conditions. The valley is affected by post-earthquake slope instability — ask at the national park office about current trail conditions.', 'Langtang National Park entry permit and a TIMS card. The park office is at Dhunche; confirm current fees with the Nepal Tourism Board.', array['Langtang National Park permit', 'TIMS card']::text[], true, true, true),
  ('a0000000-0000-4000-8000-000000000006', 'gokyo-lakes-renjo-la', 'Gokyo Lakes & Renjo La', 'A quieter Khumbu itinerary built around the Gokyo lakes, Gokyo Ri and the Renjo La crossing to Thame.', 'The Gokyo valley branches west from Namche and climbs past Dole and Machhermo to the turquoise lakes below Gokyo Ri. The viewpoint above the lakes gives a different angle on Everest and the Ngozumpa glacier than Kala Patthar, and the crossing of the Renjo La to Thame makes a loop rather than an out-and-back. Compared with the EBC trail, there are fewer lodges and fewer trekkers, so plan for basic facilities above Machhermo.', 'Khumbu', 'd0000000-0000-4000-8000-000000000001', 'hard', 'trekking', 120, 12, 5357, 3100, 'Lukla (Tenzing–Hillary Airport)', 27.6875, 86.7315, array['spring', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Gokyo_Lakes%2C_Dudh_Pokhari%2C_Nepal%2C_Himalayas.jpg/1920px-Gokyo_Lakes%2C_Dudh_Pokhari%2C_Nepal%2C_Himalayas.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Gokyo_Ri_summit%2C_Gokyo_Lake%2C_Nepal%2C_Himalayas.jpg/1920px-Gokyo_Ri_summit%2C_Gokyo_Lake%2C_Nepal%2C_Himalayas.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Namche_Bazaar%2C_Mountains%2C_Nepal.jpg/1920px-Namche_Bazaar%2C_Mountains%2C_Nepal.jpg']::text[], '{"type":"LineString","coordinates":[[86.7315,27.6875],[86.7128,27.7408],[86.7132,27.8048],[86.6778,27.8596],[86.698,27.906],[86.693,27.953],[86.683,27.957],[86.639,27.977],[86.629,27.926],[86.632,27.827],[86.7132,27.8048],[86.7315,27.6875]]}'::jsonb, '[{"day":1,"title":"Lukla → Phakding","description":"Easy descent and river walk to the first teahouse.","altitudeM":2610,"walkingHours":"3–4 h","accommodation":"Teahouse, Phakding"},{"day":2,"title":"Phakding → Namche Bazaar","description":"Bridges, the park gate and the climb to Namche.","altitudeM":3440,"walkingHours":"6 h","accommodation":"Teahouse, Namche"},{"day":3,"title":"Acclimatisation in Namche","description":"Syangboche or Khunde day walk and an early night.","altitudeM":3440,"walkingHours":"3 h optional","accommodation":"Teahouse, Namche"},{"day":4,"title":"Namche → Dole","description":"Climb away from the main valley into the Gokyo drainage.","altitudeM":4200,"walkingHours":"5 h","accommodation":"Teahouse, Dole"},{"day":5,"title":"Dole → Machhermo","description":"Short day through juniper to the last sizeable settlement before the lakes.","altitudeM":4470,"walkingHours":"4 h","accommodation":"Teahouse, Machhermo"},{"day":6,"title":"Machhermo → Gokyo","description":"Pass the first and second lakes to the village on the third lake.","altitudeM":4790,"walkingHours":"4–5 h","accommodation":"Teahouse, Gokyo"},{"day":7,"title":"Gokyo Ri","description":"Climb Gokyo Ri for Cho Oyu, Everest and the Ngozumpa glacier, then rest.","altitudeM":5357,"walkingHours":"4 h","accommodation":"Teahouse, Gokyo"},{"day":8,"title":"Gokyo → Renjo La → Lungden","description":"Cross the Renjo La and descend steeply to the Bhote Koshi side.","altitudeM":5340,"walkingHours":"7–8 h","accommodation":"Teahouse, Lungden"},{"day":9,"title":"Lungden → Thame","description":"Descend past yak pastures to the monastery village of Thame.","altitudeM":3800,"walkingHours":"4–5 h","accommodation":"Teahouse, Thame"},{"day":10,"title":"Thame → Namche Bazaar","description":"Short contour back to Namche for a rest afternoon.","altitudeM":3440,"walkingHours":"3–4 h","accommodation":"Teahouse, Namche"},{"day":11,"title":"Namche → Lukla","description":"Long descent through Monjo and Phakding.","altitudeM":2860,"walkingHours":"8 h","accommodation":"Lodge, Lukla"},{"day":12,"title":"Lukla → Kathmandu","description":"Weather-dependent morning flight.","altitudeM":1400,"walkingHours":"—","accommodation":"Hotel, Kathmandu"}]'::jsonb, array['Teahouses at Dole, Machhermo, Gokyo, Lungden and Thame — thinner than the EBC trail', 'Charging and hot water are limited and cost extra above Machhermo', 'No ATMs or medical posts beyond Namche', 'Basic lodges may close outside spring and autumn']::text[], 'The Renjo La is a genuine high pass with steep snow on the descent and no shelter at the top. Do not attempt it alone or in poor visibility. Gokyo Ri is a steep two-hour climb at 5,000 m plus; start early. Carry cash for the whole valley and expect simple food above Machhermo.', 'Sagarmatha National Park permit and Khumbu Pasanglhamu Rural Municipality fee, checked at Monjo.', array['Sagarmatha National Park permit', 'Khumbu Pasanglhamu Rural Municipality fee']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000007', 'manaslu-circuit-trek', 'Manaslu Circuit Trek', 'A restricted-area circuit from the Budhi Gandaki gorge over the Larke Pass into the Marsyangdi valley.', 'The Manaslu Circuit is a long, varied trek that starts on the road north of Arughat, follows the Budhi Gandaki through Machha Khola, Jagat, Deng and Namrung, and crosses the Larke Pass at 5,106 m before descending to Dharapani. Tibetan-influenced villages, mani walls and monasteries sit below Manaslu itself. Permits are restricted and must be arranged through a licensed Nepali agency; the route is usually walked with a guide and at least one other trekker.', 'Manaslu', 'd0000000-0000-4000-8000-000000000004', 'strenuous', 'trekking', 180, 14, 5106, 4700, 'Soti Khola, Gorkha', 28.028, 84.806, array['spring', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Mt_Manaslu_from_Manaslu_basecamp.jpg/1920px-Mt_Manaslu_from_Manaslu_basecamp.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Mt_Manaslu_from_Manaslu_basecamp.jpg/1920px-Mt_Manaslu_from_Manaslu_basecamp.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Annapurna_Massif-IMG_5221-Pano.jpg/1920px-Annapurna_Massif-IMG_5221-Pano.jpg']::text[], '{"type":"LineString","coordinates":[[84.806,28.028],[84.788,28.125],[84.767,28.251],[84.717,28.399],[84.672,28.505],[84.639,28.579],[84.612,28.616],[84.527,28.642],[84.463,28.548],[84.363,28.482]]}'::jsonb, '[{"day":1,"title":"Kathmandu → Soti Khola","description":"Long road journey to the road head above Arughat.","altitudeM":700,"walkingHours":"—","accommodation":"Guesthouse, Soti Khola"},{"day":2,"title":"Soti Khola → Machha Khola","description":"River-level walking with a few short climbs.","altitudeM":870,"walkingHours":"6 h","accommodation":"Teahouse, Machha Khola"},{"day":3,"title":"Machha Khola → Jagat","description":"Climb around the gorge and pass the restricted-area checkpoint.","altitudeM":1340,"walkingHours":"6 h","accommodation":"Teahouse, Jagat"},{"day":4,"title":"Jagat → Deng","description":"Narrow gorge, waterfalls and suspension bridges.","altitudeM":1860,"walkingHours":"6 h","accommodation":"Teahouse, Deng"},{"day":5,"title":"Deng → Namrung","description":"Climb into the Tibetan-influenced upper valley.","altitudeM":2630,"walkingHours":"6 h","accommodation":"Teahouse, Namrung"},{"day":6,"title":"Namrung → Lho","description":"Mani walls and gompas, with Manaslu appearing above the village.","altitudeM":3180,"walkingHours":"5 h","accommodation":"Teahouse, Lho"},{"day":7,"title":"Lho → Samagaun","description":"Short day to the main settlement below Manaslu.","altitudeM":3530,"walkingHours":"4 h","accommodation":"Teahouse, Samagaun"},{"day":8,"title":"Acclimatisation in Samagaun","description":"Walk to Birendra Tal or the Pungen Gompa ridge, then rest.","altitudeM":3530,"walkingHours":"3 h optional","accommodation":"Teahouse, Samagaun"},{"day":9,"title":"Samagaun → Samdo","description":"High pasture and yak herding settlements near the Tibetan border.","altitudeM":3860,"walkingHours":"4 h","accommodation":"Teahouse, Samdo"},{"day":10,"title":"Samdo → Larkya Bazar","description":"Short day to the seasonal stone houses below the pass.","altitudeM":4460,"walkingHours":"4 h","accommodation":"Basic lodge, Larkya Bazar"},{"day":11,"title":"Larke Pass → Bimthang","description":"Long, exposed crossing of the Larke Pass then a steep descent.","altitudeM":5106,"walkingHours":"9–10 h","accommodation":"Teahouse, Bimthang"},{"day":12,"title":"Bimthang → Tilije","description":"Forest descent into the Marsyangdi valley.","altitudeM":2300,"walkingHours":"6–7 h","accommodation":"Teahouse, Tilije"},{"day":13,"title":"Tilije → Dharapani → Besisahar","description":"Join the Annapurna Circuit trail, then road transfer down valley.","altitudeM":1860,"walkingHours":"3 h","accommodation":"Guesthouse, Besisahar"},{"day":14,"title":"Besisahar → Kathmandu","description":"Road journey back to the capital.","altitudeM":1400,"walkingHours":"—","accommodation":"Hotel, Kathmandu"}]'::jsonb, array['Basic teahouses in most villages; simple dormitories at Larkya Bazar', 'No ATMs beyond Arughat — carry enough cash for the whole circuit', 'Limited electricity and hot water above Deng', 'Checkpoint at Jagat for restricted-area permits']::text[], 'This is a restricted area: solo trekking is not permitted and permits must be obtained through a licensed agency. The Larke Pass is exposed, can hold snow into spring, and has a long descent on the far side; start before dawn and turn back in bad weather. Landslides close the road approach in monsoon. Travel insurance must cover high-altitude trekking and helicopter evacuation.', 'Manaslu Conservation Area Permit, Annapurna Conservation Area Permit and a Manaslu restricted-area permit. The restricted permit is issued through a licensed Nepali agency for a minimum group of two trekkers; confirm current fees and rules with the Nepal Tourism Board.', array['MCAP permit', 'ACAP permit', 'Restricted-area permit']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000008', 'upper-mustang-trek', 'Upper Mustang Trek', 'A dry, high-desert trek from Jomsom through Kagbeni to the walled city of Lo Manthang.', 'Upper Mustang follows the Kali Gandaki north of Kagbeni into the old Kingdom of Lo. The landscape is eroded cliff and desert rather than forest, with whitewashed villages, cave complexes and gompas along the way. The route can be walked from Jomsom or shortened with a jeep road that now reaches Lo Manthang. A restricted-area permit and a licensed agency are required beyond Kagbeni.', 'Mustang', 'd0000000-0000-4000-8000-000000000005', 'hard', 'trekking', 110, 10, 3840, 1700, 'Jomsom, Mustang', 28.7807, 83.7227, array['spring', 'summer', 'autumn']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/The_kingdom_of_Lo%2C_Lomangthang%2C_Upper_Mustang_%28Pano%29.jpg/1920px-The_kingdom_of_Lo%2C_Lomangthang%2C_Upper_Mustang_%28Pano%29.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Kagbeni%2C_Paddies_2%2C_Mustang%2C_Nepal.jpg/1280px-Kagbeni%2C_Paddies_2%2C_Mustang%2C_Nepal.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Thorong_La_Pass%2C_Nepal.jpg/1920px-Thorong_La_Pass%2C_Nepal.jpg']::text[], '{"type":"LineString","coordinates":[[83.7227,28.7807],[83.767,28.815],[83.817,28.861],[83.846,28.918],[83.867,29],[83.956,29.19]]}'::jsonb, '[{"day":1,"title":"Pokhara → Jomsom → Kagbeni","description":"Morning flight or drive, then a short walk to Kagbeni on the Kali Gandaki.","altitudeM":2810,"walkingHours":"2 h","accommodation":"Guesthouse, Kagbeni"},{"day":2,"title":"Kagbeni → Chele","description":"Enter the restricted area and climb above the river through clay cliffs.","altitudeM":3050,"walkingHours":"5 h","accommodation":"Teahouse, Chele"},{"day":3,"title":"Chele → Geling","description":"Cross the Taklam La and Yamda La passes between eroded ridges.","altitudeM":3570,"walkingHours":"6 h","accommodation":"Teahouse, Geling"},{"day":4,"title":"Geling → Tsarang","description":"High desert plateau to the monastery town of Tsarang.","altitudeM":3560,"walkingHours":"5 h","accommodation":"Guesthouse, Tsarang"},{"day":5,"title":"Tsarang → Lo Manthang","description":"Cross the Lo La and descend to the walled capital of the old kingdom.","altitudeM":3840,"walkingHours":"5 h","accommodation":"Guesthouse, Lo Manthang"},{"day":6,"title":"Lo Manthang and Chhoser","description":"Rest day with a side trip to the Jhong caves and Namgyal Gompa.","altitudeM":3840,"walkingHours":"3 h optional","accommodation":"Guesthouse, Lo Manthang"},{"day":7,"title":"Lo Manthang → Ghami","description":"Return south on the alternative trail past Dhakmar and its red cliffs.","altitudeM":3520,"walkingHours":"6–7 h","accommodation":"Teahouse, Ghami"},{"day":8,"title":"Ghami → Kagbeni","description":"Long descent back through the passes to the Kali Gandaki.","altitudeM":2810,"walkingHours":"7–8 h","accommodation":"Guesthouse, Kagbeni"},{"day":9,"title":"Kagbeni → Muktinath → Jomsom","description":"Optional visit to Muktinath temple, then road or trail to Jomsom.","altitudeM":2720,"walkingHours":"4 h","accommodation":"Guesthouse, Jomsom"},{"day":10,"title":"Jomsom → Pokhara","description":"Early flight or drive down the Kali Gandaki, which is often windy in the afternoon.","altitudeM":1400,"walkingHours":"—","accommodation":"Hotel, Pokhara"}]'::jsonb, array['Guesthouses in Kagbeni, Chele, Geling, Tsarang and Lo Manthang', 'Jeep road now reaches Lo Manthang; walking is optional in places', 'No ATMs north of Jomsom', 'Very dry and windy conditions; water is scarce']::text[], 'This is a restricted area requiring a permit and a registered guide. The Kali Gandaki valley is one of the windiest places in Nepal; afternoon flights from Jomsom are frequently cancelled. Altitude stays below 4,000 m but the dry air, dust and cold nights are demanding. Carry cash, water treatment and sun protection.', 'Upper Mustang restricted-area permit (issued for a minimum of 10 days) and an ACAP permit, arranged through a licensed Nepali agency. Confirm current fees and rules with the Nepal Tourism Board.', array['Upper Mustang restricted-area permit', 'ACAP permit']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000009', 'nagarkot-dhulikhel-ridge-walk', 'Nagarkot to Dhulikhel Ridge Walk', 'A one-day valley-rim walk between two hill towns, with a Himalayan sunrise at the start.', 'This point-to-point day walk follows the Kathmandu Valley rim from Nagarkot to Dhulikhel through terraced fields, pine and sal forest, and small Tamang and Newar settlements. On clear mornings the northern skyline runs from Langtang to Ganesh Himal and, on the best days, Everest. It is a good acclimatisation or rest-day walk at low altitude, with road access at both ends.', 'Kathmandu Valley', 'd0000000-0000-4000-8000-000000000006', 'easy', 'hiking', 15, 1, 2175, 450, 'Nagarkot viewpoint', 27.7154, 85.5206, array['spring', 'autumn', 'winter']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Sunset_view_of_Everest.jpg/1920px-Sunset_view_of_Everest.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Nepal_-_Bhaktapur_Nyatapola_temple.jpg/1920px-Nepal_-_Bhaktapur_Nyatapola_temple.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Historic_Pagoda_Style_Architecture_in_Kathmandu_Durbar_Square-IMG_4069.jpg/1920px-Historic_Pagoda_Style_Architecture_in_Kathmandu_Durbar_Square-IMG_4069.jpg']::text[], '{"type":"LineString","coordinates":[[85.5206,27.7154],[85.5301,27.6941],[85.5394,27.6683],[85.5442,27.6412],[85.5508,27.6222]]}'::jsonb, '[{"day":1,"title":"Nagarkot → Dhulikhel","description":"Ridge trail through farmland and forest; a guide is useful for the junctions. Return by local bus or private car.","altitudeM":2175,"walkingHours":"5–6 h","accommodation":"—"}]'::jsonb, array['Tea shops and villages every hour or so', 'Road access at Nagarkot, Nala and Dhulikhel', 'Hotels and restaurants at both ends', 'Local buses from Dhulikhel back to Kathmandu']::text[], 'Paths are partly farm tracks and can be muddy after rain. There are few waymarks at junctions; download an offline map or walk with a local guide. Leeches are common in the monsoon and the ridge is exposed to afternoon storms.', 'No trekking permit is required for this day walk. Some sections cross community forest with a small local entry fee.', '{}'::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000010', 'chitwan-buffer-zone-walk', 'Chitwan Buffer Zone Walk', 'A guided lowland walk through riverine forest and grassland on the edge of Chitwan National Park.', 'Walking in Chitwan is restricted to the buffer zone and community forests unless you are with an authorised park guide on a permitted route. A half or full-day walk from Sauraha passes sal forest, tall elephant grass and the Rapti riverbank, with a realistic chance of seeing deer, monkeys and birds, and a much smaller chance of rhinoceros or tiger. It is a low-altitude, high-interest contrast to a mountain itinerary.', 'Chitwan', 'd0000000-0000-4000-8000-000000000007', 'easy', 'hiking', 8, 1, 200, 20, 'Sauraha, Chitwan', 27.579, 84.494, array['autumn', 'winter', 'spring']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg/1920px-Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg/1920px-Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Pokhara%2C_Phewa_Lake%2C_Nepal.jpg/1920px-Pokhara%2C_Phewa_Lake%2C_Nepal.jpg']::text[], '{"type":"LineString","coordinates":[[84.494,27.579],[84.5072,27.5701],[84.5189,27.5632]]}'::jsonb, '[{"day":1,"title":"Sauraha community forest walk","description":"Guided morning and afternoon walk with a licensed nature guide; canoe trip on the Rapti at a suitable water level.","altitudeM":200,"walkingHours":"3–5 h","accommodation":"—"}]'::jsonb, array['Licensed guides available in Sauraha', 'Park entry point at Kasara for jeep and canoe activities', 'Lodges and restaurants in Sauraha', 'Bird hides and viewing towers in the buffer zone']::text[], 'Never walk inside the national park without an authorised guide. Rhinoceros and elephants are dangerous at close range: keep distance, stay quiet and follow your guide. Leeches and mosquitoes are common in the monsoon; use repellent and long sleeves.', 'Chitwan National Park entry fee applies for park activities; buffer-zone community forest walks carry a small local fee. A licensed guide is mandatory.', array['Chitwan National Park entry fee', 'Licensed guide']::text[], true, false, true),
  ('a0000000-0000-4000-8000-000000000011', 'kathmandu-heritage-walk', 'Kathmandu Heritage Walk', 'A walking route between Boudhanath and Bhaktapur Durbar Square, connecting two of the valley’s great monuments.', 'This city walk links Boudhanath, one of the largest stupas in Nepal, with the Newar architecture of Bhaktapur Durbar Square. Between them the route passes smaller bahals, markets and the terraced edge of the valley. It is sightseeing rather than trekking: short distances, low altitude, and a lot of time spent looking up. Traffic between the two sites is heavy, so use a taxi for the connecting leg and walk the historic cores.', 'Kathmandu Valley', 'd0000000-0000-4000-8000-000000000006', 'easy', 'sightseeing', 5, 1, 1400, 40, 'Boudhanath Stupa', 27.7215, 85.362, array['spring', 'autumn', 'winter']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Nepal_-_Bhaktapur_Nyatapola_temple.jpg/1920px-Nepal_-_Bhaktapur_Nyatapola_temple.jpg', array['https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Historic_Pagoda_Style_Architecture_in_Kathmandu_Durbar_Square-IMG_4069.jpg/1920px-Historic_Pagoda_Style_Architecture_in_Kathmandu_Durbar_Square-IMG_4069.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Nepal_-_Bhaktapur_Nyatapola_temple.jpg/1920px-Nepal_-_Bhaktapur_Nyatapola_temple.jpg']::text[], '{"type":"LineString","coordinates":[[85.362,27.7215],[85.3821,27.7062],[85.4062,27.6852],[85.4298,27.671]]}'::jsonb, '[{"day":1,"title":"Boudhanath and Bhaktapur","description":"Kora around the stupa in the morning, then Bhaktapur’s squares and pottery square in the afternoon. Tickets are separate for each monument zone.","altitudeM":1400,"walkingHours":"3–4 h","accommodation":"—"}]'::jsonb, array['Cafes and restaurants around Boudhanath and Bhaktapur', 'Entry tickets for Bhaktapur Durbar Square and some monasteries', 'Taxis and ride-hailing in Kathmandu', 'Accessible paved walking in both historic cores']::text[], 'Streets are uneven and crowded, with motorbikes on pavements; watch your footing and your belongings. Air quality is poor in winter. Dress modestly at religious sites and walk clockwise around stupas and shrines.', 'No trekking permit. Bhaktapur Durbar Square and some monument zones charge an entry ticket for foreign visitors.', '{}'::text[], true, false, true)
insert into public.guides (id, slug, full_name, region, languages, specialties, experience_years, day_rate_npr, bio, contact_email, contact_phone, verified, published, is_sample) values
  ('b0000000-0000-4000-8000-000000000001', 'tenzing-sherpa-khumbu', 'Tenzing Sherpa', 'Khumbu', array['Nepali', 'English', 'Sherpa']::text[], array['High-altitude trekking', 'Everest Base Camp', 'Photography walks']::text[], 12, 4500, 'Sample listing. Khumbu-born guide with twelve seasons on the EBC and Gokyo routes, including winter crossings. Works with small groups and emphasises slow acclimatisation.', null, null, false, true, true),
  ('b0000000-0000-4000-8000-000000000002', 'anjali-gurung-annapurna', 'Anjali Gurung', 'Annapurna', array['Nepali', 'English', 'French']::text[], array['Annapurna Base Camp', 'Gurung village stays', 'First-time trekkers']::text[], 8, 4000, 'Sample listing. Gurung guide from Ghandruk who leads ABC and Poon Hill itineraries with a focus on village hospitality and local food.', null, null, false, true, true),
  ('b0000000-0000-4000-8000-000000000003', 'dawa-tamang-langtang', 'Dawa Tamang', 'Langtang', array['Nepali', 'English', 'Tamang']::text[], array['Langtang Valley', 'Helambu', 'Birding']::text[], 10, 3800, 'Sample listing. Tamang guide from the Langtang valley, with ten seasons of valley and Helambu routes and a serious interest in highland birds.', null, null, false, true, true),
  ('b0000000-0000-4000-8000-000000000004', 'sunita-rai-valley-and-terai', 'Sunita Rai', 'Kathmandu Valley', array['Nepali', 'English', 'Hindi']::text[], array['Day hikes', 'Kathmandu heritage', 'Chitwan nature walks']::text[], 6, 3200, 'Sample listing. Day-hike guide based in Kathmandu, covering valley-rim trails and heritage walks, with nature-guide training for Chitwan buffer-zone walks.', null, null, false, true, true)
insert into public.stays (id, slug, name, type, region, destination_id, description, price_per_night_npr, amenities, photo_url, contact_email, lat, lng, published, is_sample) values
  ('c0000000-0000-4000-8000-000000000001', 'kyanjin-gompa-guest-house', 'Kyanjin Gompa Guest House', 'teahouse', 'Langtang', 'd0000000-0000-4000-8000-000000000003', 'Sample listing. Simple teahouse rooms beside the monastery in Kyanjin Gompa, with a shared dining hall, dal bhat and a wood stove. Hot showers are available when the solar system is charged.', 1800, array['Shared bathroom', 'Dining hall', 'Solar power', 'Luggage storage']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Kyanjin_Gompa_Village_Rasuwa.jpg/1920px-Kyanjin_Gompa_Village_Rasuwa.jpg', null, 28.2404, 85.5602, true, true),
  ('c0000000-0000-4000-8000-000000000002', 'namche-hillside-lodge', 'Namche Hillside Lodge', 'lodge', 'Khumbu', 'd0000000-0000-4000-8000-000000000001', 'Sample listing. Family-run lodge on the upper terraces of Namche Bazaar with twin rooms, a bakery counter and a sunny dining room. Useful as an acclimatisation base.', 3500, array['Private bathroom', 'Wi-fi', 'Bakery', 'Heated dining room', 'Charging']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Namche_Bazaar%2C_Nepal.jpg/1920px-Namche_Bazaar%2C_Nepal.jpg', null, 27.8048, 86.7132, true, true),
  ('c0000000-0000-4000-8000-000000000003', 'pokhara-lakeside-homestay', 'Pokhara Lakeside Homestay', 'homestay', 'Annapurna', 'd0000000-0000-4000-8000-000000000002', 'Sample listing. Three-room homestay a short walk from Phewa Lake, used as a staging point before Annapurna treks. Home-cooked meals and a rooftop for sunrise views of Machapuchare.', 2800, array['Breakfast included', 'Wi-fi', 'Rooftop terrace', 'Laundry']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Pokhara%2C_Phewa_Lake%2C_Nepal.jpg/1920px-Pokhara%2C_Phewa_Lake%2C_Nepal.jpg', null, 28.2096, 83.9558, true, true),
  ('c0000000-0000-4000-8000-000000000004', 'sauraha-community-lodge', 'Sauraha Community Lodge', 'lodge', 'Chitwan', 'd0000000-0000-4000-8000-000000000007', 'Sample listing. Low-rise lodge on the edge of Sauraha with fan rooms, a garden and a licensed nature guide on call for buffer-zone walks and canoe trips.', 3200, array['Fan rooms', 'Garden', 'Guide service', 'Restaurant']::text[], 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg/1920px-Indian_rhinoceros_%28Rhinoceros_unicornis%29_1.jpg', null, 27.579, 84.494, true, true)
